{
  "name": "adm-zip-roundtrip",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "adm-zip": "0.6.1"
  },
  "devDependencies": {
    "@types/adm-zip": "0.6.0",
    "@types/node": "26.6.5",
    "tsx": "4.23.15"
  }
}

import AdmZip from "adm-zip";

export type EntryInput = { path: string; data: string | Buffer };

function toContent(data: string | Buffer): Buffer {
  return typeof data === "string" ? Buffer.from(data, "utf8") : data;
}

export function buildZip(entries: EntryInput[]): AdmZip {
  const zip = new AdmZip();
  for (const entry of entries) {
    zip.addFile(entry.path, toContent(entry.data));
  }
  return zip;
}

export function pack(entries: EntryInput[]): Buffer {
  return buildZip(entries).toBuffer();
}

export function writeZip(entries: EntryInput[], targetPath: string): string {
  buildZip(entries).writeZip(targetPath);
  return targetPath;
}

export function openArchive(source: Buffer | string): AdmZip {
  return new AdmZip(source as string);
}

export function listEntries(source: Buffer | string): string[] {
  return openArchive(source)
    .getEntries()
    .map((entry) => entry.entryName);
}

export function readAsText(source: Buffer | string, entryPath: string): string {
  const entry = openArchive(source).getEntry(entryPath);
  if (!entry) {
    throw new Error(`entry not found: ${entryPath}`);
  }
  return entry.getData().toString("utf8");
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  listEntries,
  openArchive,
  pack,
  readAsText,
  writeZip,
} from "../src/archive.ts";

test("roundtrips string entries through a buffer", () => {
  const buf = pack([
    { path: "hello.txt", data: "hello world" },
    { path: "nested/data.json", data: JSON.stringify({ ok: true }) },
  ]);

  assert.deepEqual(listEntries(buf).sort(), ["hello.txt", "nested/data.json"]);
  assert.equal(readAsText(buf, "hello.txt"), "hello world");
  assert.equal(readAsText(buf, "nested/data.json"), '{"ok":true}');
});

test("stores folder entries and raw buffers", () => {
  const bytes = Buffer.from([0x00, 0x01, 0x02, 0xff]);
  const buf = pack([
    { path: "assets/", data: "" },
    { path: "assets/logo.bin", data: bytes },
  ]);

  assert.deepEqual(listEntries(buf).sort(), ["assets/", "assets/logo.bin"]);
  const entry = openArchive(buf).getEntry("assets/logo.bin");
  assert.ok(entry);
  assert.deepEqual(entry.getData(), bytes);
  assert.deepEqual(readAsText(buf, "assets/"), "");
});

test("writes a zip to a temp path and reads it back", async () => {
  const dir = await mkdtemp(join(tmpdir(), "adm-zip-"));
  try {
    const target = join(dir, "archive.zip");
    writeZip(
      [
        { path: "a.txt", data: "alpha" },
        { path: "b.txt", data: "beta" },
      ],
      target,
    );

    const raw = await readFile(target);
    assert.deepEqual(listEntries(target).sort(), ["a.txt", "b.txt"]);
    assert.equal(readAsText(raw, "a.txt"), "alpha");
    assert.equal(readAsText(target, "b.txt"), "beta");
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("throws for a missing entry", () => {
  const buf = pack([{ path: "only.txt", data: "x" }]);
  assert.throws(() => readAsText(buf, "missing.txt"), /entry not found/);
});

from aiohttp import web


def make_app():
    app = web.Application()
    app["users"] = {1: {"id": 1, "name": "Ada"}, 2: {"id": 2, "name": "Linus"}}
    app.router.add_get("/health", health)
    app.router.add_get("/users/{id}", get_user)
    app.router.add_post("/users", create_user)
    return app


async def health(request):
    return web.json_response({"status": "ok"})


async def get_user(request):
    user = request.app["users"].get(int(request.match_info["id"]))
    if user is None:
        raise web.HTTPNotFound(text="user not found")
    return web.json_response(user)


async def create_user(request):
    payload = await request.json()
    name = payload.get("name")
    if not name:
        raise web.HTTPBadRequest(text="name is required")
    users = request.app["users"]
    user = {"id": max(users) + 1, "name": name}
    users[user["id"]] = user
    return web.json_response(user, status=201)

import fcntl
import socket
import struct

import pytest

_IFF_UP = 0x1
_SIOCGIFFLAGS = 0x8913
_SIOCSIFFLAGS = 0x8914


def _enable_loopback():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            ifreq = struct.pack("16sH", b"lo", 0)
            flags = struct.unpack("16sH", fcntl.ioctl(sock, _SIOCGIFFLAGS, ifreq))[1]
            if not flags & _IFF_UP:
                fcntl.ioctl(sock, _SIOCSIFFLAGS, struct.pack("16sH", b"lo", flags | _IFF_UP))
    except OSError:
        pass


@pytest.fixture(scope="session", autouse=True)
def loopback():
    _enable_loopback()

