import Ajv, { type ErrorObject } from "ajv";
import addFormats from "ajv-formats";

const ajv = new Ajv({ allErrors: true, removeAdditional: "all", coerceTypes: true });
addFormats(ajv);

export const userSchema = {
  type: "object",
  additionalProperties: false,
  required: ["email", "name"],
  properties: {
    email: { type: "string", format: "email" },
    name: { type: "string", minLength: 1, maxLength: 80 },
    age: { type: "integer", minimum: 13 },
    website: { type: "string", format: "uri" },
    id: { type: "string", format: "uuid" },
  },
} as const;

export const validateUser = ajv.compile(userSchema);

export function fieldErrors(errors: ErrorObject[] | null | undefined) {
  const out: Record<string, string[]> = {};
  for (const e of errors ?? []) {
    const key = (e.instancePath || "/").replace(/^\//, "") || e.params?.missingProperty || "_";
    (out[key] ??= []).push(e.message ?? e.keyword);
  }
  return out;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { fieldErrors, validateUser } from "../src/validate.ts";

test("accepts a valid payload and strips extras", () => {
  const data: Record<string, unknown> = {
    email: "a@example.com",
    name: "Ada",
    age: "30",
    admin: true,
    id: "123e4567-e89b-12d3-a456-426614174000",
  };
  assert.equal(validateUser(data), true);
  assert.equal(data.admin, undefined);
  assert.equal(data.age, 30);
});

test("rejects bad email and missing name", () => {
  assert.equal(validateUser({ email: "nope" }), false);
  const errs = fieldErrors(validateUser.errors);
  assert.ok(errs.email || errs._);
  assert.ok(Object.keys(errs).length >= 1);
});

{
  "name": "ajv-standalone-validation",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
