from apscheduler.executors.pool import ThreadPoolExecutor
from apscheduler.jobstores.memory import MemoryJobStore
from apscheduler.schedulers.background import BackgroundScheduler


def build_scheduler(paused: bool = False) -> BackgroundScheduler:
    # MemoryJobStore holds jobs in this process only; nothing survives a restart.
    scheduler = BackgroundScheduler(
        jobstores={"default": MemoryJobStore()},
        executors={"default": ThreadPoolExecutor(2)},
        job_defaults={"coalesce": True, "max_instances": 1, "misfire_grace_time": 5},
    )
    scheduler.start(paused=paused)
    return scheduler


def schedule_interval(scheduler, func, seconds, job_id):
    return scheduler.add_job(func, "interval", seconds=seconds, id=job_id)


def schedule_once(scheduler, func, run_at, job_id):
    return scheduler.add_job(func, "date", run_date=run_at, id=job_id)

from datetime import datetime, UTC
from zoneinfo import ZoneInfo

from apscheduler.triggers.cron import CronTrigger
from apscheduler.triggers.interval import IntervalTrigger

TZ = ZoneInfo("America/New_York")

def report_trigger() -> CronTrigger:
    return CronTrigger(hour=9, minute=0, timezone=TZ)

def heartbeat_trigger(start: datetime | None = None) -> IntervalTrigger:
    return IntervalTrigger(minutes=15, start_date=start, timezone=UTC)

def next_report(now: datetime | None = None) -> datetime:
    if now is None:
        now = datetime.now(TZ)
    return report_trigger().get_next_fire_time(None, now)

def upcoming(trigger, now: datetime, count: int) -> list[datetime]:
    fire = trigger.get_next_fire_time(None, now)
    out = []
    while fire is not None and len(out) < count:
        out.append(fire)
        fire = trigger.get_next_fire_time(fire, fire)
    return out

