} from "../src/decimal.ts";

test("0.1 + 0.2 equals 0.3 with big.js", () => {
  assert.notEqual(0.1 + 0.2, 0.3);
  const sum = add("0.1", "0.2");
  assert.equal(sum.toString(), "0.3");
  assert.equal(equals(sum, "0.3"), true);
  assert.equal(new Big("0.1").plus("0.2").eq("0.3"), true);
});

