import bleach
from markupsafe import Markup

ALLOWED_TAGS = ["a", "b", "code", "em", "i", "li", "ol", "p", "strong", "ul"]
ALLOWED_ATTRS = {"a": ["href", "title"]}
ALLOWED_PROTOCOLS = ["http", "https", "mailto"]


def sanitize(html: str) -> str:
    # strip=False escapes disallowed tags, strip=True deletes them.
    return bleach.clean(
        html,
        tags=ALLOWED_TAGS,
        attributes=ALLOWED_ATTRS,
        protocols=ALLOWED_PROTOCOLS,
        strip=False,
        strip_comments=True,
    )


def sanitize_strict(html: str) -> str:
    return bleach.clean(html, tags=[], attributes={}, protocols=[], strip=True)


def safe(html: str) -> Markup:
    # bleach always returns a plain str, so mark it safe AFTER cleaning.
    return Markup(sanitize(html))


def render_card(title: str, body_html: str) -> Markup:
    template = Markup('<article class="card"><h1>{}</h1><div>{}</div></article>')
    # Markup.format escapes plain args but leaves Markup args alone.
    return template.format(title, safe(body_html))


def autolink(text: str) -> Markup:
    # linkify alone does NOT sanitize, so clean first to avoid passing scripts through.
    return Markup(bleach.linkify(sanitize_strict(text)))

from blinker import Namespace

events = Namespace()

user_saved = events.signal("user-saved", "Sent after a user is persisted.")
user_deleted = events.signal("user-deleted", "Sent after a user is removed.")


class UserStore:
    """Emits named signals with itself as the sender."""

    def __init__(self, name: str):
        self.name = name

    def save(self, user_id: int, email: str):
        return user_saved.send(self, user_id=user_id, email=email)

    def delete(self, user_id: int):
        return user_deleted.send(self, user_id=user_id)


class AuditLog:
    """Records only the events of the stores it is subscribed to."""

    def __init__(self):
        self.entries: list[tuple[str, int, str | None]] = []

    def subscribe(self, store: UserStore):
        user_saved.connect(self.on_saved, sender=store)
        user_deleted.connect(self.on_deleted, sender=store)

    def on_saved(self, sender: UserStore, user_id: int, email: str):
        self.entries.append((sender.name, user_id, email))

    def on_deleted(self, sender: UserStore, user_id: int):
        self.entries.append((sender.name, user_id, None))

import time

from boltons.cacheutils import cachedmethod, cachedproperty
from boltons.funcutils import wraps


class RetryError(Exception):
    """Raised when a retried callable exhausts every attempt."""


def retry(attempts=3, retry_on=Exception, delay=0.0, sleep=time.sleep):
    """Signature-preserving retry decorator built on boltons.funcutils.wraps.

    Calls the wrapped function up to *attempts* times, retrying only when an
    exception matching *retry_on* is raised. The final failure is re-raised as
    a RetryError whose __cause__ is the last original exception.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(attempts):
                try:
                    return func(*args, **kwargs)
                except retry_on as exc:
                    last = exc
                    if attempt < attempts - 1:
                        sleep(delay)
            raise RetryError(f"{func.__name__} failed after {attempts} attempts") from last
        return wrapper
    return decorator


class Rollup:
    """In-memory aggregator showing boltons cachedproperty and cachedmethod."""

    def __init__(self, values):
        self.values = list(values)
        self.calls = {"total": 0, "bucket": 0}
        self._buckets = {}

    @cachedproperty
    def total(self):
        self.calls["total"] += 1
        return sum(self.values)

    @cachedmethod("_buckets")
    def bucket(self, width):
        self.calls["bucket"] += 1
        return self.total // width


class Slotted:
    __slots__ = ("x",)

    def __init__(self, x):
        self.x = x

    @cachedproperty
    def doubled(self):
        return self.x * 2

from boltons.iterutils import get_path, remap

SECRET_KEYS = {"password", "token", "secret", "api_key"}
_UNSET = object()


def redact_secrets(obj, keys=SECRET_KEYS, mask="***"):
    def visit(path, key, value):
        if isinstance(key, str) and key.lower() in keys:
            return key, mask
        return True

    return remap(obj, visit)


def drop_nones(obj):
    def visit(path, key, value):
        if value is None:
            return False
        return True

    return remap(obj, visit)


def rename_keys(obj, mapping):
    def visit(path, key, value):
        if key in mapping:
            return mapping[key], value
        return True

    return remap(obj, visit)


def nested_get(obj, path, default=_UNSET):
    if default is _UNSET:
        return get_path(obj, path)
    return get_path(obj, path, default=default)

