import time

import funcy
from cachetools import TTLCache


def ttl_memoize(ttl, maxsize=128, key=None, timer=time.monotonic):
    cache = TTLCache(maxsize=maxsize, ttl=ttl, timer=timer)

    def decorate(func):
        @funcy.wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs) if key else args + tuple(sorted(kwargs.items()))
            try:
                return cache[k]
            except KeyError:
                cache[k] = value = func(*args, **kwargs)
                return value

        wrapper.memory = cache
        wrapper.invalidate_all = cache.clear
        return wrapper

    return decorate


def retrying_loader(loader, ttl=30.0, timer=time.monotonic, tries=3):
    @funcy.retry(tries=tries, timeout=0)
    @ttl_memoize(ttl=ttl, timer=timer)
    def load(key):
        return loader(key)

    return load


def fetch_or_default(load, key, default):
    return funcy.fallback(lambda: load(key), lambda: default)

from cachetools import LRUCache, TTLCache, cached, cachedmethod


def build_square(timer, ttl=10.0, maxsize=128):
    cache = TTLCache(maxsize=maxsize, ttl=ttl, timer=timer)
    stats = {"calls": 0}

    @cached(cache)
    def square(n):
        stats["calls"] += 1
        return n * n

    return square, cache, stats


def build_row_lookup(rows):
    cache = TTLCache(maxsize=8, ttl=60)

    @cached(cache, key=lambda row: row["id"])
    def lookup(row):
        return rows[row["id"]]

    return lookup, cache


class RepoClient:
    shared = TTLCache(maxsize=32, ttl=60)

    def __init__(self, owner):
        self.owner = owner
        self.calls = 0

    @cachedmethod(lambda self: self.shared)
    def repo(self, name):
        self.calls += 1
        return f"{self.owner}/{name}"


def build_lru(maxsize=2):
    return LRUCache(maxsize=maxsize)

