from __future__ import annotations

from dataclasses import dataclass

import chardet

CONFIDENCE_FLOOR = 0.5


@dataclass(frozen=True)
class Detection:
    encoding: str | None
    confidence: float
    language: str | None
    text: str


def detect_bytes(data: bytes, *, include: list[str] | None = None) -> Detection:
    """Detect the charset of one sample and decode it with that guess."""
    result = chardet.detect(data, include_encodings=include)
    encoding = result["encoding"]
    text = "" if encoding is None else data.decode(encoding, errors="replace")
    return Detection(encoding, result["confidence"], result["language"], text)


def decode_or_fallback(data: bytes, fallback: str = "cp1252", floor: float = CONFIDENCE_FLOOR) -> str:
    """Trust chardet only above the floor, otherwise decode with a known fallback."""
    detection = detect_bytes(data)
    if detection.encoding is None or detection.confidence < floor:
        return data.decode(fallback, errors="replace")
    return detection.text

from __future__ import annotations

from dataclasses import dataclass

from charset_normalizer import from_bytes, is_binary


@dataclass(frozen=True)
class Decoded:
    text: str
    encoding: str
    bom: bool
    language: str
    ambiguous: tuple[str, ...]


def decode_sample(data: bytes, *, cp_isolation: list[str] | None = None) -> Decoded:
    """Decode one byte sample, recording every charset that fits equally well."""
    match = from_bytes(data, cp_isolation=cp_isolation).best()
    if match is None:
        raise ValueError("no text encoding matched the sample")
    return Decoded(
        text=str(match),
        encoding=match.encoding,
        bom=match.bom,
        language=match.language,
        ambiguous=tuple(match.could_be_from_charset),
    )


def decode_mixed(samples: list[bytes]) -> list[Decoded]:
    """Decode a batch where each sample may use a different encoding."""
    decoded: list[Decoded] = []
    for sample in samples:
        if is_binary(sample):
            raise ValueError("binary sample cannot be decoded as text")
        decoded.append(decode_sample(sample))
    return decoded

