from datetime import UTC, datetime
from zoneinfo import ZoneInfo

import click
from dateutil.rrule import rrulestr


def next_runs(rule: str, tz_name: str, count: int = 3) -> list[datetime]:
    tz = ZoneInfo(tz_name)
    now = datetime.now(tz).replace(microsecond=0)
    rs = rrulestr(rule, dtstart=now)
    # rrule builds wall-clock datetimes, and a time inside a DST gap (02:30 on the
    # spring-forward day) resolves to a real instant. Round-tripping through UTC
    # makes that instant explicit and gives the correct local wall time.
    return [dt.astimezone(UTC).astimezone(tz) for dt in rs.xafter(now, count=count)]


@click.command()
@click.argument("rule")
@click.option("--tz", default="UTC", show_default=True, help="IANA time zone name.")
@click.option("-n", "--count", default=3, show_default=True, type=click.IntRange(min=1))
def main(rule: str, tz: str, count: int) -> None:
    """Print the next run times for an RFC 5545 RRULE, e.g. "FREQ=DAILY;BYHOUR=9"."""
    try:
        runs = next_runs(rule, tz, count)
    except (ValueError, KeyError) as exc:
        raise click.UsageError(str(exc)) from exc
    for run in runs:
        click.echo(run.isoformat())


if __name__ == "__main__":
    main()

import click
from rich.console import Console
from rich.progress import (
    BarColumn,
    Progress,
    SpinnerColumn,
    TextColumn,
    TimeElapsedColumn,
)
from rich.status import Status


def normalize(item: str) -> str:
    if not item.strip():
        raise ValueError("empty item")
    return item.strip().lower().replace(" ", "-")


def make_progress(console: Console, transient: bool) -> Progress:
    return Progress(
        SpinnerColumn(),
        TextColumn("[bold blue]{task.description}"),
        BarColumn(),
        TextColumn("{task.completed}/{task.total}"),
        TimeElapsedColumn(),
        console=console,
        transient=transient,
    )


def run_batch(items, console: Console, transient: bool = True):
    with Status("[bold]validating[/]", console=console):
        for item in items:
            normalize(item)
    results = []
    with make_progress(console, transient) as progress:
        task = progress.add_task("processing", total=len(items))
        for item in items:
            results.append(normalize(item))
            progress.advance(task)
    return results


@click.command()
@click.argument("items", nargs=-1, required=True)
@click.option("--transient/--no-transient", default=True, help="Erase bars when done.")
def main(items, transient):
    console = Console()
    results = run_batch(items, console, transient=transient)
    console.print(f"[green]done[/] {len(results)} items")
    for result in results:
        console.print(result)


if __name__ == "__main__":
    main()

