function capture() {
  let output = "";
  const stream = new Writable({
    write(chunk, _encoding, callback) {
      output += chunk.toString();
      callback();
    },
  });

  return {
    stream,
    get output() {
      return output;
    },
  };
}

function makeContext() {
  const stdout = capture();
  const stderr = capture();

  return {
    stdout,
    stderr,
    context: {
      ...Cli.defaultContext,
      stdout: stdout.stream,
      stderr: stderr.stream,
    },
  };
}

