from datetime import datetime
from itertools import islice

from croniter import croniter

def next_runs(expr: str, start: datetime, count: int = 1, day_or: bool = True) -> list[datetime]:
    it = croniter(expr, start, day_or=day_or)
    return [it.get_next(datetime) for _ in range(count)]

def prev_runs(expr: str, start: datetime, count: int = 1) -> list[datetime]:
    it = croniter(expr, start)
    return [it.get_prev(datetime) for _ in range(count)]

def upcoming(expr: str, start: datetime, count: int) -> list[datetime]:
    # all_next() is an infinite generator: always bound it with islice.
    it = croniter(expr, start)
    return list(islice(it.all_next(datetime), count))

def is_valid(expr: str) -> bool:
    return croniter.is_valid(expr)

from cryptography.fernet import Fernet, InvalidToken, MultiFernet


def new_key() -> str:
    return Fernet.generate_key().decode()


class KeyRing:
    def __init__(self, keys: list[str]):
        self.keys = list(keys)
        self._mf = MultiFernet([Fernet(k.encode()) for k in self.keys])

    @classmethod
    def generate(cls) -> "KeyRing":
        return cls([new_key()])

    def add(self, key: str) -> None:
        self.keys.insert(0, key)
        self._mf = MultiFernet([Fernet(k.encode()) for k in self.keys])

    def drop(self, key: str) -> None:
        self.keys.remove(key)
        self._mf = MultiFernet([Fernet(k.encode()) for k in self.keys])

    def encrypt(self, data: str) -> str:
        return self._mf.encrypt(data.encode()).decode()

    def decrypt(self, token: str) -> str:
        return self._mf.decrypt(token.encode()).decode()

    def rotate(self, token: str) -> str:
        return self._mf.rotate(token.encode()).decode()

import base64

from cryptography.hazmat.primitives import hashes, hmac
from passlib.context import CryptContext

bcrypt_ctx = CryptContext(schemes=["bcrypt"], bcrypt__rounds=12)


def pepper(password: str, key: bytes) -> bytes:
    h = hmac.HMAC(key, hashes.SHA256())
    h.update(password.encode("utf-8"))
    return base64.b64encode(h.finalize())


def hash_password(password: str, key: bytes) -> str:
    return bcrypt_ctx.hash(pepper(password, key))


def verify_password(password: str, stored_hash: str, key: bytes) -> bool:
    return bcrypt_ctx.verify(pepper(password, key), stored_hash)


def needs_rehash(stored_hash: str) -> bool:
    return bcrypt_ctx.needs_update(stored_hash)


def hash_scheme(stored_hash: str) -> str | None:
    return bcrypt_ctx.identify(stored_hash)

