    a = Event(name="x", at=datetime.fromisoformat("2024-01-01T00:00:00+00:00"))
    b = Event(name="x", at=datetime.fromisoformat("2023-12-31T19:00:00-05:00"))
    assert diff_models(a, b) == {}
