import { test } from "node:test";
import assert from "node:assert/strict";
import { createStore, type Item } from "../src/store.ts";

let seq = 0;
function fresh() {
  return createStore(`provenpin-test-${seq++}`);
}

const seed: Item[] = [
  { sku: "A", category: "books", price: 12, createdAt: 1 },
  { sku: "B", category: "books", price: 30, createdAt: 2 },
  { sku: "C", category: "toys", price: 18, createdAt: 3 },
];

test("bulkAdd inserts rows and equals query filters by index", async () => {
  const db = fresh();
  const ids = await db.items.bulkAdd(seed, { allKeys: true });
  assert.equal(ids.length, 3);

  const books = await db.items.where("category").equals("books").toArray();
  assert.equal(books.length, 2);
  assert.deepEqual(
    books.map((b) => b.sku).sort(),
    ["A", "B"],
  );

  await db.delete();
});

test("between query returns an inclusive price range", async () => {
  const db = fresh();
  await db.items.bulkAdd(seed, { allKeys: true });

  const mid = await db.items.where("price").between(10, 20).toArray();
  assert.deepEqual(
    mid.map((i) => i.sku).sort(),
    ["A", "C"],
  );

  await db.delete();
});

test("compound index query matches category and price together", async () => {
  const db = fresh();
  await db.items.bulkAdd(seed, { allKeys: true });

  const hit = await db.items.where("[category+price]").equals(["books", 30]).first();
  assert.equal(hit?.sku, "B");

  const none = await db.items.where("[category+price]").equals(["toys", 30]).first();
  assert.equal(none, undefined);

  await db.delete();
});

test("update modifies matching rows in place", async () => {
  const db = fresh();
  await db.items.bulkAdd(seed, { allKeys: true });

  const updated = await db.items.where("sku").equals("A").modify({ price: 15 });
  assert.equal(updated, 1);

  const row = await db.items.where("sku").equals("A").first();
  assert.equal(row?.price, 15);

  await db.delete();
});

test("transaction rolls back when it throws", async () => {
  const db = fresh();
  await db.items.bulkAdd(seed, { allKeys: true });

  await assert.rejects(
    db.transaction("rw", db.items, async () => {
      await db.items.add({ sku: "X", category: "toys", price: 5, createdAt: 4 });
      assert.equal(await db.items.count(), 4);
      throw new Error("rollback-me");
    }),
    /rollback-me/,
  );

  assert.equal(await db.items.count(), 3);
  assert.equal(await db.items.where("sku").equals("X").first(), undefined);

  await db.delete();
});

from __future__ import annotations

import threading
from collections.abc import Iterator, MutableMapping
from typing import Any, Callable

from cachetools import LRUCache
from cachetools.keys import hashkey
from diskcache import FanoutCache

MISSING = object()


class TieredCache(MutableMapping):
    """L1 cachetools.LRUCache promoted from an L2 diskcache.FanoutCache."""

    def __init__(self, directory: str, maxsize: int = 128, shards: int = 4, size_limit: int = 1 << 24):
        self.memory: LRUCache = LRUCache(maxsize=maxsize)
        self.disk: FanoutCache = FanoutCache(directory, shards=shards, size_limit=size_limit)
        self._lock = threading.RLock()
        self.stats = {"memory": 0, "disk": 0, "miss": 0}

    def __getitem__(self, key: Any) -> Any:
        with self._lock:
            if key in self.memory:
                self.stats["memory"] += 1
                return self.memory[key]
        value = self.disk.get(key, default=MISSING)
        if value is MISSING:
            self.stats["miss"] += 1
            raise KeyError(key)
        with self._lock:
            self.memory[key] = value
        self.stats["disk"] += 1
        return value

    def __setitem__(self, key: Any, value: Any) -> None:
        self.set(key, value)

    def __delitem__(self, key: Any) -> None:
        with self._lock:
            self.memory.pop(key, None)
        del self.disk[key]

    def __iter__(self) -> Iterator[Any]:
        return iter(self.disk)

    def __len__(self) -> int:
        return len(self.disk)

    def set(self, key: Any, value: Any, expire: float | None = None) -> None:
        with self._lock:
            self.memory[key] = value
        self.disk.set(key, value, expire=expire)

    def hits(self) -> tuple[int, int]:
        return self.stats["memory"], self.stats["disk"]

    def close(self) -> None:
        self.disk.close()

    def __enter__(self) -> "TieredCache":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()


def memoize(cache: MutableMapping, key: Callable[..., Any] = hashkey):
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            cache_key = key(*args, **kwargs)
            try:
                return cache[cache_key]
            except KeyError:
                value = func(*args, **kwargs)
                cache[cache_key] = value
                return value

        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper

    return decorator

import hashlib
import json
from pathlib import Path
from typing import Any, Callable

from diskcache import FanoutCache
from filelock import FileLock

MISSING = object()


def job_key(name: str, *args: Any) -> str:
    payload = json.dumps([name, args], sort_keys=True, default=repr)
    digest = hashlib.sha256(payload.encode()).hexdigest()[:16]
    return f"{name}-{digest}"


class JobCache:
    def __init__(self, directory: str, shards: int = 4, timeout: float = 1.0, lock_timeout: float = 5.0):
        self.directory = Path(directory)
        self.directory.mkdir(parents=True, exist_ok=True)
        (self.directory / "locks").mkdir(parents=True, exist_ok=True)
        self.cache = FanoutCache(str(self.directory / "cache"), shards=shards, timeout=timeout)
        self.lock_timeout = lock_timeout
        self._locks: dict[str, FileLock] = {}

    def _lock(self, key: str) -> FileLock:
        lock = self._locks.get(key)
        if lock is None:
            lock = self._locks[key] = FileLock(str(self.directory / "locks" / f"{key}.lock"), timeout=self.lock_timeout)
        return lock

    def run_once(self, name: str, func: Callable[..., Any], *args: Any, expire: float | None = None) -> Any:
        key = job_key(name, *args)
        hit = self.cache.get(key, default=MISSING)
        if hit is not MISSING:
            return hit
        with self._lock(key):
            hit = self.cache.get(key, default=MISSING)
            if hit is not MISSING:
                return hit
            value = func(*args)
            self.cache.set(key, value, expire=expire)
            return value

    def claim(self, name: str, *args: Any) -> bool:
        return self.cache.add(job_key(name, *args), True)

    def close(self) -> None:
        self.cache.close()

