  chainId: 1,
  verifyingContract: "0x000000000000000000000000000000000000dEaD",
};

export const MAIL_TYPES: Record<string, TypedDataField[]> = {
  Mail: [
    { name: "from", type: "address" },
    { name: "to", type: "address" },
    { name: "contents", type: "string" },
  ],
