        if "@" not in v:
            raise ValueError("not an email")
        return v.lower()

    @model_validator(mode="after")
    def bulk_needs_bank(self):
        if self.quantity > 50 and self.payment.kind != "bank":
            raise ValueError("orders over 50 units must pay by bank transfer")
        return self

