import { encode, decode } from "html-entities";

export type EntityLevel = "xml" | "html4" | "html5" | "all";
export type EncodeModeName = "specialChars" | "nonAscii";

export function encodeHtml(
  input: string,
  mode: EncodeModeName = "specialChars",
  level: EntityLevel = "html5",
): string {
  return encode(input, { mode, level });
}

export function decodeHtml(input: string, level: EntityLevel = "html5"): string {
  return decode(input, { level });
}

export function escapeUserContent(input: string): string {
  return encodeHtml(input, "specialChars", "html5");
}

export function escapeAttribute(input: string): string {
  return encodeHtml(input, "specialChars", "xml");
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  encodeHtml,
  decodeHtml,
  escapeUserContent,
  escapeAttribute,
} from "../src/html-entities.ts";

test("encodes HTML special characters with the specialChars mode", () => {
  assert.equal(
    encodeHtml("<script>a & b</script>"),
    "&lt;script&gt;a &amp; b&lt;/script&gt;",
  );
});

test("specialChars mode leaves non-ASCII characters untouched", () => {
  const input = "café";
  const encoded = encodeHtml(input, "specialChars");
  assert.equal(encoded.includes("é"), true);
  assert.equal(decodeHtml(encoded), input);
});

test("nonAscii mode escapes non-ASCII characters", () => {
  const input = "café";
  const encoded = encodeHtml(input, "nonAscii");
  assert.equal(encoded.includes("é"), false);
  assert.equal(decodeHtml(encoded), input);
});

test("decodes named entities", () => {
  assert.equal(decodeHtml("&copy; &amp; &lt;b&gt;"), "© & <b>");
});

test("decodes decimal and hexadecimal numeric entities", () => {
  assert.equal(decodeHtml("&#65;&#x42;&#67;"), "ABC");
});

test("escapes untrusted user content safely", () => {
  const payload = '<img src=x onerror="alert(1)">';
  const safe = escapeUserContent(payload);
  assert.equal(safe.includes("<"), false);
  assert.equal(safe.includes(">"), false);
  assert.equal(safe.includes('"'), false);
  assert.equal(decodeHtml(safe), payload);
});

test("escapes values for attribute contexts", () => {
  const value = `Tom & "Jerry"`;
  const safe = escapeAttribute(value);
  assert.equal(safe, "Tom &amp; &quot;Jerry&quot;");
  assert.equal(decodeHtml(safe), value);
});

from authlib.integrations.httpx_client import AsyncOAuth2Client


class ApiClient:
    def __init__(self, client_id, client_secret, token_url, api_url):
        self.api_url = api_url.rstrip("/")
        self.oauth = AsyncOAuth2Client(
            client_id=client_id,
            client_secret=client_secret,
            token_endpoint=token_url,
            grant_type="client_credentials",
        )

    async def fetch_token(self):
        return await self.oauth.fetch_token()

    async def get(self, path):
        return await self.oauth.get(f"{self.api_url}/{path.lstrip('/')}")

    async def aclose(self):
        await self.oauth.aclose()

import httpx
from pydantic import BaseModel

class Repo(BaseModel):
    id: int
    full_name: str
    stargazers_count: int

class ApiClient:
    def __init__(self, base_url: str = "https://api.example.com", retries: int = 2):
        self.http = httpx.AsyncClient(base_url=base_url, timeout=10)
        self.retries = retries

    async def __aenter__(self):
        return self

    async def __aexit__(self, *exc):
        await self.http.aclose()

    async def get_repo(self, owner: str, name: str) -> Repo:
        for attempt in range(self.retries + 1):
            try:
                r = await self.http.get(f"/repos/{owner}/{name}")
            except httpx.TransportError:
                if attempt == self.retries:
                    raise
                continue
            if r.status_code < 500 or attempt == self.retries:
                break
        r.raise_for_status()
        # validate raw bytes: invalid JSON also surfaces as pydantic ValidationError
        return Repo.model_validate_json(r.content)

