import type { Redis } from "ioredis";

export function createCache(redis: Redis, prefix = "cache:") {
  const inflight = new Map<string, Promise<unknown>>();
  return {
    async getOrSet<T>(key: string, ttlSeconds: number, load: () => Promise<T>): Promise<T> {
      const k = prefix + key;
      const hit = await redis.get(k);
      if (hit !== null) return JSON.parse(hit) as T;
      // single flight: concurrent misses share one load
      if (!inflight.has(k)) {
        inflight.set(k, (async () => {
          try {
            const value = await load();
            await redis.set(k, JSON.stringify(value), "EX", ttlSeconds);
            return value;
          } finally { inflight.delete(k); }
        })());
      }
      return inflight.get(k) as Promise<T>;
    },
    invalidate: (key: string) => redis.del(prefix + key),
    ttl: (key: string) => redis.ttl(prefix + key),
  };
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import RedisMock from "ioredis-mock";
import type { Redis } from "ioredis";
import { createCache } from "../src/cache";

let redis: Redis;
beforeEach(async () => { redis = new (RedisMock as any)() as Redis; await redis.flushall(); });

describe("cache-aside", () => {
  it("loads once then serves from redis", async () => {
    const cache = createCache(redis);
    const load = vi.fn(async () => ({ id: 1, name: "Ada" }));
    expect(await cache.getOrSet("user:1", 60, load)).toEqual({ id: 1, name: "Ada" });
    expect(await cache.getOrSet("user:1", 60, load)).toEqual({ id: 1, name: "Ada" });
    expect(load).toHaveBeenCalledTimes(1);
    expect(await cache.ttl("user:1")).toBeGreaterThan(0);
  });

  it("concurrent misses share one load", async () => {
    const cache = createCache(redis);
    const load = vi.fn(async () => { await new Promise((r) => setTimeout(r, 10)); return 42; });
    expect(await Promise.all([1, 2, 3].map(() => cache.getOrSet("n", 60, load)))).toEqual([42, 42, 42]);
    expect(load).toHaveBeenCalledTimes(1);
  });

  it("invalidate forces a reload; failed loads are not cached", async () => {
    const cache = createCache(redis);
    await cache.getOrSet("k", 60, async () => 1);
    await cache.invalidate("k");
    expect(await cache.getOrSet("k", 60, async () => 2)).toBe(2);
    await expect(cache.getOrSet("x", 60, async () => { throw new Error("db down"); })).rejects.toThrow("db down");
    expect(await redis.exists("cache:x")).toBe(0);
  });
});

import unicodedata

import jellyfish


def normalize(name):
    # NFKD + ascii drop makes matching accent and case insensitive
    ascii_name = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode()
    return " ".join(ascii_name.upper().split())


def soundex_key(name):
    # soundex is a fixed 4-char code, so unrelated surnames often collide
    return jellyfish.soundex(normalize(name))


def metaphone_key(name):
    # metaphone is variable length and collapses non-letters to an empty string
    return jellyfish.metaphone(normalize(name))


def similarity(a, b):
    return jellyfish.jaro_winkler_similarity(normalize(a), normalize(b))


def is_match(a, b, threshold=0.9):
    na, nb = normalize(a), normalize(b)
    if not na or not nb:
        return False
    if na == nb:
        return True
    ma, mb = metaphone_key(na), metaphone_key(nb)
    if ma and ma == mb:
        return True
    return similarity(na, nb) >= threshold


def best_match(query, candidates):
    scored = ((c, similarity(query, c)) for c in candidates)
    choice, score = max(scored, key=lambda pair: pair[1], default=(None, 0.0))
    return {"choice": choice, "score": score}

