import { compile, type JSONSchema } from "json-schema-to-typescript";

export const orderSchema: JSONSchema = {
  title: "Order",
  type: "object",
  additionalProperties: false,
  required: ["id", "status", "items"],
  properties: {
    id: { type: "string", description: "Order id, e.g. ord_123" },
    status: { type: "string", enum: ["pending", "paid", "shipped"] },
    note: { type: "string" },
    items: { type: "array", items: { $ref: "#/definitions/LineItem" }, minItems: 1 },
  },
  definitions: {
    LineItem: {
      type: "object",
      additionalProperties: false,
      required: ["sku", "qty"],
      properties: { sku: { type: "string" }, qty: { type: "integer", minimum: 1 } },
    },
  },
};

export async function generateTypes(schema: JSONSchema, name: string): Promise<string> {
  return compile(schema, name, {
    bannerComment: "/* Generated from JSON Schema. Do not edit. */",
    additionalProperties: false,
    strictIndexSignatures: true,
    style: { singleQuote: false, semi: true },
  });
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { generateTypes, orderSchema } from "../src/codegen.ts";

test("generates interfaces with required, optional and enum fields", async () => {
  const ts = await generateTypes(orderSchema, "Order");
  assert.match(ts, /^\/\* Generated from JSON Schema\. Do not edit\. \*\//);
  assert.match(ts, /export interface Order \{/);
  assert.match(ts, /\n\s+id: string;/);
  assert.match(ts, /status: "pending" \| "paid" \| "shipped";/);
  assert.match(ts, /note\?: string;/);
  assert.match(ts, /items: \[LineItem, \.\.\.LineItem\[\]\];/);
});

test("$ref definitions become their own interfaces", async () => {
  const ts = await generateTypes(orderSchema, "Order");
  assert.match(ts, /export interface LineItem \{/);
  assert.match(ts, /sku: string;/);
  assert.match(ts, /qty: number;/);
  assert.doesNotMatch(ts, /\[k: string\]: unknown/);
});

test("descriptions become JSDoc comments", async () => {
  const ts = await generateTypes(orderSchema, "Order");
  assert.match(ts, /\/\*\*\n\s+\* Order id, e\.g\. ord_123\n\s+\*\/\n\s+id: string;/);
});

test("open objects keep an index signature when allowed", async () => {
  const ts = await generateTypes({ title: "Meta", type: "object", additionalProperties: true, properties: { a: { type: "number" } } }, "Meta");
  // strictIndexSignatures adds "| undefined" so lookups by unknown keys stay honest.
  assert.match(ts, /\[k: string\]: unknown \| undefined;/);
});

from jsonschema import Draft202012Validator, FormatChecker
from referencing import Registry
from referencing.jsonschema import DRAFT202012

ADDRESS = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://example.com/schemas/address",
    "type": "object",
    "properties": {
        "street": {"type": "string", "minLength": 1},
        "postcode": {"type": "string", "pattern": r"^[0-9]{5}$"},
    },
    "required": ["street"],
    "unevaluatedProperties": False,
}

PERSON = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://example.com/schemas/person",
    "type": "object",
    "properties": {
        "name": {"type": "string", "minLength": 1},
        "born": {"type": "string", "format": "date"},
        "address": {"$ref": "https://example.com/schemas/address"},
    },
    "required": ["name", "address"],
    "unevaluatedProperties": False,
}

TREE = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://example.com/schemas/tree",
    "$dynamicAnchor": "node",
    "type": "object",
    "properties": {
        "value": {"type": "integer"},
        "children": {"type": "array", "items": {"$dynamicRef": "#node"}},
    },
    "required": ["value"],
    "unevaluatedProperties": False,
}

def build_registry() -> Registry:
    return Registry().with_resources(
        [(s["$id"], DRAFT202012.create_resource(s)) for s in (ADDRESS, PERSON, TREE)]
    )

def errors(schema, instance, formats=False):
    checker = FormatChecker() if formats else None
    validator = Draft202012Validator(schema, registry=build_registry(), format_checker=checker)
    return sorted(validator.iter_errors(instance), key=lambda e: list(e.absolute_path))

import pytest
from referencing import Resource
from referencing.exceptions import CannotDetermineSpecification
from referencing.jsonschema import DRAFT202012

from schemas import PERSON, TREE, errors

VALID = {
    "name": "Ada",
    "born": "1815-12-10",
    "address": {"street": "12 Baker St", "postcode": "12345"},
}

def test_valid_document_passes():
    assert errors(PERSON, VALID) == []

def test_ref_constraints_apply_across_resources():
    bad = {**VALID, "address": {"street": "12 Baker St", "postcode": "nope"}}
    (err,) = errors(PERSON, bad)
    assert list(err.absolute_path) == ["address", "postcode"]
    assert err.validator == "pattern"

def test_unevaluated_properties_sees_through_ref():
    person_level = {**VALID, "nickname": "Ada"}
    assert errors(PERSON, person_level)[0].validator == "unevaluatedProperties"
    address_level = {**VALID, "address": {**VALID["address"], "country": "UK"}}
    (err,) = errors(PERSON, address_level)
    assert err.validator == "unevaluatedProperties"

def test_format_is_annotation_only_unless_checker_passed():
    bad = {**VALID, "born": "not-a-date"}
    assert errors(PERSON, bad) == []
    (err,) = errors(PERSON, bad, formats=True)
    assert err.validator == "format" and err.instance == "not-a-date"

def test_dynamic_ref_recurses_into_children():
    doc = {"value": 1, "children": [{"value": 2}, {"value": "x"}]}
    (err,) = errors(TREE, doc)
    assert list(err.absolute_path) == ["children", 1, "value"]

def test_from_contents_needs_schema_or_default():
    with pytest.raises(CannotDetermineSpecification):
        Resource.from_contents({"type": "object"})
    resource = Resource.from_contents({"type": "object"}, default_specification=DRAFT202012)
    assert resource.contents == {"type": "object"}

