import { parseHTML } from "linkedom";

export type PageInfo = { title: string; description: string | null; og: Record<string, string>; links: string[] };

export function extractInfo(html: string, baseUrl: string): PageInfo {
  const { document } = parseHTML(html);
  const og: Record<string, string> = {};
  for (const m of document.querySelectorAll('meta[property^="og:"]')) {
    og[m.getAttribute("property")!.slice(3)] = m.getAttribute("content") ?? "";
  }
  const links = [...document.querySelectorAll("a[href]")]
    .map((a) => new URL(a.getAttribute("href")!, baseUrl).href)
    .filter((href, i, all) => href.startsWith("http") && all.indexOf(href) === i);
  return {
    title: document.querySelector("title")?.textContent?.trim() ?? "",
    description: document.querySelector('meta[name="description"]')?.getAttribute("content") ?? null,
    og,
    links,
  };
}

/** Absolutize links and images, lazy-load images, and drop inline scripts. */
export function rewrite(html: string, baseUrl: string): string {
  const { document } = parseHTML(html);
  for (const a of document.querySelectorAll("a[href]")) a.setAttribute("href", new URL(a.getAttribute("href")!, baseUrl).href);
  for (const img of document.querySelectorAll("img[src]")) {
    img.setAttribute("src", new URL(img.getAttribute("src")!, baseUrl).href);
    img.setAttribute("loading", "lazy");
  }
  for (const s of document.querySelectorAll("script:not([src])")) s.remove();
  return document.toString();
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { extractInfo, rewrite } from "../src/page.ts";

const html = `<!doctype html>
<html><head>
  <title> Kenai Parts </title>
  <meta name="description" content="Parts and tools">
  <meta property="og:title" content="Kenai Parts">
  <meta property="og:image" content="https://cdn.example.com/og.png">
</head><body>
  <a href="/catalog">Catalog</a>
  <a href="about">About</a>
  <a href="https://other.example.org/x">Other</a>
  <a href="/catalog">Dup</a>
  <a href="mailto:hi@example.com">Mail</a>
  <img src="/img/bolt.png" alt="bolt">
  <script>track()</script>
  <script src="/app.js"></script>
</body></html>`;

test("extracts title, description, Open Graph and unique absolute links", () => {
  assert.deepEqual(extractInfo(html, "https://example.com/shop/"), {
    title: "Kenai Parts",
    description: "Parts and tools",
    og: { title: "Kenai Parts", image: "https://cdn.example.com/og.png" },
    links: ["https://example.com/catalog", "https://example.com/shop/about", "https://other.example.org/x"],
  });
});

test("rewrites URLs, lazy-loads images and removes inline scripts", () => {
  const out = rewrite(html, "https://example.com/shop/");
  assert.match(out, /<a href="https:\/\/example.com\/catalog">Catalog<\/a>/);
  // linkedom does not keep attribute order, so check each attribute on its own.
  const img = out.match(/<img [^>]+>/)![0];
  assert.match(img, /src="https:\/\/example.com\/img\/bolt.png"/);
  assert.match(img, /alt="bolt"/);
  assert.match(img, /loading="lazy"/);
  assert.doesNotMatch(out, /track\(\)/);
  assert.match(out, /<script src="\/app.js"><\/script>/);
  assert.match(out, /^<!DOCTYPE html>/i);
});

from litestar import Litestar, Request, delete, get
from litestar.connection import ASGIConnection
from litestar.di import Provide
from litestar.exceptions import NotAuthorizedException, PermissionDeniedException
from litestar.handlers import BaseRouteHandler
from litestar.response import Response


class ItemNotFound(Exception):
    pass


class ItemRepo:
    def __init__(self, items: dict[int, str] | None = None):
        self.items = items if items is not None else {1: "widget"}

    def get(self, item_id: int) -> str:
        if item_id not in self.items:
            raise ItemNotFound(item_id)
        return self.items[item_id]

    def delete(self, item_id: int) -> None:
        if self.items.pop(item_id, None) is None:
            raise ItemNotFound(item_id)


async def provide_repo() -> ItemRepo:
    # swap for a real database session in production
    return ItemRepo()


def role_guard(connection: ASGIConnection, handler: BaseRouteHandler) -> None:
    # demo only: trusts a header; use a verified token in production
    required = handler.opt.get("role")
    if required is None:
        return
    role = connection.headers.get("x-role")
    if role is None:
        raise NotAuthorizedException("missing credentials")
    if role != required:
        raise PermissionDeniedException(f"requires role {required}")


@get("/items/{item_id:int}")
async def get_item(item_id: int, repo: ItemRepo) -> dict:
    return {"id": item_id, "name": repo.get(item_id)}


@delete("/items/{item_id:int}", opt={"role": "admin"})
async def delete_item(item_id: int, repo: ItemRepo) -> None:
    repo.delete(item_id)


def item_not_found(request: Request, exc: ItemNotFound) -> Response:
    return Response({"error": "item not found", "id": exc.args[0]}, status_code=404)


ROUTES = [get_item, delete_item]
GUARDS = [role_guard]
HANDLERS = {ItemNotFound: item_not_found}

app = Litestar(
    route_handlers=ROUTES,
    dependencies={"repo": Provide(provide_repo)},
    guards=GUARDS,
    exception_handlers=HANDLERS,
)

