async function withTempFile(fn: (file: string) => Promise<void>): Promise<void> {
  const dir = await mkdtemp(join(tmpdir(), "lowdb-"));
  try {
    await fn(join(dir, "db.json"));
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

