from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional

import marshmallow as ma
import marshmallow_dataclass


@dataclass
class Address:
    street: str
    city: str


@dataclass
class Contact:
    email: str = field(metadata={"validate": ma.validate.Email()})
    phone: Optional[str] = None


@dataclass
class User:
    id: int = field(metadata={"data_key": "user_id"})
    name: str = field(metadata={"validate": ma.validate.Length(min=1)})
    joined: date
    address: Address
    contacts: List[Contact] = field(default_factory=list)
    nickname: Optional[str] = None


@dataclass
class UserPatch:
    name: Optional[str] = None
    nickname: Optional[str] = None


class ExcludeUnknown(ma.Schema):
    class Meta:
        unknown = ma.EXCLUDE


UserSchema = marshmallow_dataclass.class_schema(User)
LenientUserSchema = marshmallow_dataclass.class_schema(User, base_schema=ExcludeUnknown)
PatchSchema = marshmallow_dataclass.class_schema(UserPatch)

from datetime import date

import pytest
from marshmallow import ValidationError

from schemas import (
    Address,
    Contact,
    LenientUserSchema,
    PatchSchema,
    User,
    UserPatch,
    UserSchema,
)

RAW = {
    "user_id": 7,
    "name": "Ada",
    "joined": "2024-01-02",
    "address": {"street": "1 Main", "city": "Springfield"},
    "contacts": [{"email": "ada@example.com", "phone": "555"}],
}


def test_load_builds_nested_dataclasses():
    user = UserSchema().load(RAW)
    assert isinstance(user, User)
    assert isinstance(user.address, Address)
    assert isinstance(user.contacts[0], Contact)
    assert user.joined == date(2024, 1, 2)


def test_dump_round_trips_to_primitives():
    user = UserSchema().load(RAW)
    dumped = UserSchema().dump(user)
    assert dumped == {**RAW, "nickname": None}
    assert UserSchema().load(dumped) == user


def test_validation_error_exposes_nested_paths():
    bad = {**RAW, "contacts": [{"email": "not-an-email"}]}
    with pytest.raises(ValidationError) as exc:
        UserSchema().load(bad)
    assert exc.value.messages == {"contacts": {0: {"email": ["Not a valid email address."]}}}


def test_missing_nested_record_is_required():
    with pytest.raises(ValidationError) as exc:
        UserSchema().load({k: v for k, v in RAW.items() if k != "address"})
    assert exc.value.messages == {"address": ["Missing data for required field."]}


def test_unknown_fields_are_rejected_by_default():
    with pytest.raises(ValidationError) as exc:
        UserSchema().load({**RAW, "bogus": True})
    assert exc.value.messages == {"bogus": ["Unknown field."]}
    assert LenientUserSchema().load({**RAW, "bogus": True}).id == 7


def test_partial_load_requires_optional_fields():
    with pytest.raises(TypeError):
        UserSchema(partial=True).load({"user_id": 7, "name": "Ada"})
    assert PatchSchema().load({"name": "Ada"}) == UserPatch(name="Ada")

from dataclasses import dataclass

import marshmallow as ma
from marshmallow_oneofschema import OneOfSchema


@dataclass
class EmailTarget:
    address: str


@dataclass
class SmsTarget:
    number: str


class EmailTargetSchema(ma.Schema):
    address = ma.fields.Email(required=True)

    @ma.post_load
    def make_target(self, data, **kwargs):
        return EmailTarget(**data)


class SmsTargetSchema(ma.Schema):
    number = ma.fields.Str(required=True)

    @ma.post_load
    def make_target(self, data, **kwargs):
        return SmsTarget(**data)


class TargetSchema(OneOfSchema):
    type_field = "kind"
    type_schemas = {"email": EmailTargetSchema, "sms": SmsTargetSchema}

    def get_obj_type(self, obj):
        return {EmailTarget: "email", SmsTarget: "sms"}[type(obj)]


class NotificationSchema(ma.Schema):
    id = ma.fields.Int(required=True)
    target = ma.fields.Nested(TargetSchema, required=True)

import marshmallow as ma
import pytest
from marshmallow_oneofschema import OneOfSchema

from schemas import (
    EmailTarget,
    EmailTargetSchema,
    NotificationSchema,
    SmsTarget,
    TargetSchema,
)


def test_load_dispatches_on_kind():
    loaded = NotificationSchema().load(
        {"id": 1, "target": {"kind": "email", "address": "a@b.com"}}
    )
    assert loaded["target"] == EmailTarget("a@b.com")


def test_dump_adds_kind_and_round_trips():
    dumped = NotificationSchema().dump({"id": 2, "target": SmsTarget(number="+15555550100")})
    assert dumped["target"] == {"number": "+15555550100", "kind": "sms"}
    assert NotificationSchema().load(dumped)["target"] == SmsTarget("+15555550100")


def test_unknown_kind_is_reported_on_type_field():
    with pytest.raises(ma.ValidationError) as exc:
        TargetSchema().load({"kind": "carrier-pigeon", "address": "a@b.com"})
    assert exc.value.messages == {"kind": ["Unsupported value: carrier-pigeon"]}


def test_default_get_obj_type_must_match_type_schemas_keys():
    class NoGetObjType(OneOfSchema):
        type_field = "kind"
        type_schemas = TargetSchema.type_schemas

    # the default get_obj_type returns the class name ("EmailTarget"), not the
    # "email" key, and dump silently returns an error tuple instead of raising
    result = NoGetObjType().dump(EmailTarget("a@b.com"))
    assert result == (None, {"_schema": "Unsupported object type: EmailTarget"})


def test_type_field_remove_false_leaks_type_into_subschema():
    class KeepsTypeField(OneOfSchema):
        type_field = "kind"
        type_field_remove = False
        type_schemas = {"email": EmailTargetSchema}

    with pytest.raises(ma.ValidationError) as exc:
        KeepsTypeField().load({"kind": "email", "address": "a@b.com"})
    assert exc.value.messages == {"kind": ["Unknown field."]}


def test_parent_unknown_option_does_not_reach_nested_schema():
    data = {"id": 3, "target": {"kind": "email", "address": "a@b.com", "extra": 1}}
    # unknown=EXCLUDE on the parent is not passed through fields.Nested
    with pytest.raises(ma.ValidationError):
        NotificationSchema().load(data, unknown=ma.EXCLUDE)

    class Tolerant(ma.Schema):
        id = ma.fields.Int(required=True)
        target = ma.fields.Nested(TargetSchema, required=True, unknown=ma.EXCLUDE)

    assert Tolerant().load(data)["target"] == EmailTarget("a@b.com")

