  await addCourse(db, "cits", "CITS", 8);
  await assert.rejects(addCourse(db, "cits", "dup", 8), /duplicate key|unique/i);
  await assert.rejects(addCourse(db, "long", "Too long", 200), /check/i);
  await db.destroy();
