const inboxTemplate = `mixin row(item)
  li(class=item.unread ? "unread" : "read")
    strong= item.from
    span.subject= item.subject

h1= title
if items.length
  ul.inbox
    each item in items
      +row(item)
else
  p.empty No messages`;

