test("withSeededMath patches Math.random then restores it", () => {
  const original = Math.random;
  const samples = withSeededMath("shared", () => [
    Math.random(),
    Math.random(),
    Math.random(),
  ]);
  assert.equal(Math.random, original);
  assert.deepEqual(samples, take(createRng("shared"), 3));
