        raise HTTPException(404, "Hero not found")
    session.delete(db_hero); session.commit()

from contextlib import asynccontextmanager

from starlette.applications import Starlette
from starlette.middleware import Middleware
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.responses import JSONResponse
from starlette.routing import Route


class TraceMiddleware(BaseHTTPMiddleware):
    def __init__(self, app, name):
        super().__init__(app)
        self.name = name

    async def dispatch(self, request, call_next):
        request.app.state.trace.append(f"{self.name}:in")
        response = await call_next(request)
        request.app.state.trace.append(f"{self.name}:out")
        return response


@asynccontextmanager
async def lifespan(app):
    app.state.trace = []
    app.state.items = {1: "one", 2: "two"}
    try:
        yield
    finally:
        app.state.trace.clear()
        del app.state.items


async def get_item(request):
    item_id = request.path_params["item_id"]
    if item_id not in request.app.state.items:
        return JSONResponse({"detail": "not found"}, status_code=404)
    return JSONResponse({"id": item_id, "name": request.app.state.items[item_id]})


async def crash(request):
    raise ValueError("boom")


def create_app():
    return Starlette(
        routes=[Route("/items/{item_id:int}", get_item), Route("/crash", crash)],
        middleware=[
            Middleware(TraceMiddleware, "outer"),
            Middleware(TraceMiddleware, "inner"),
        ],
        lifespan=lifespan,
    )

import json
from base64 import b64decode, b64encode

from itsdangerous import TimestampSigner
from starlette.applications import Starlette
from starlette.middleware.sessions import SessionMiddleware
from starlette.responses import JSONResponse
from starlette.routing import Route


async def login(request):
    request.session["user"] = request.path_params["user"]
    return JSONResponse({"ok": True})


async def me(request):
    return JSONResponse({"user": request.session.get("user")})


async def logout(request):
    request.session.clear()
    return JSONResponse({"ok": True})


async def stash_non_json(request):
    request.session["tags"] = {"a", "b"}
    return JSONResponse({"ok": True})


def create_app(secret_key="dev-secret", max_age=14 * 24 * 3600):
    app = Starlette(
        routes=[
            Route("/login/{user}", login),
            Route("/me", me),
            Route("/logout", logout),
            Route("/stash-non-json", stash_non_json),
        ]
    )
    app.add_middleware(SessionMiddleware, secret_key=secret_key, max_age=max_age)
    return app


def encode_session(session, secret_key, timestamp=None):
    # same wire format SessionMiddleware produces: base64(json) + sig
    data = b64encode(json.dumps(session).encode("utf-8"))
    signer = TimestampSigner(str(secret_key))
    if timestamp is not None:
        signer.get_timestamp = lambda: timestamp
    return signer.sign(data).decode("utf-8")

