import { Hono } from "hono";
import { Webhook, WebhookVerificationError } from "svix";

export type Event = { type: string; data: Record<string, unknown> };

/** Hono route that verifies Svix (and Svix-style, e.g. Clerk/Resend) webhooks on the raw body. */
export function makeApp(secret: string, onEvent: (e: Event, id: string) => void) {
  const wh = new Webhook(secret);
  const seen = new Set<string>();
  const app = new Hono();
  app.post("/webhooks", async (c) => {
    const raw = await c.req.text(); // must verify the exact bytes, never re-serialized JSON
    const headers = {
      "svix-id": c.req.header("svix-id") ?? "",
      "svix-timestamp": c.req.header("svix-timestamp") ?? "",
      "svix-signature": c.req.header("svix-signature") ?? "",
    };
    let evt: Event;
    try {
      // svix 2.x verify() returns undefined (1.x returned the parsed payload), so parse after it passes.
      wh.verify(raw, headers);
      evt = JSON.parse(raw) as Event;
    } catch (e) {
      if (e instanceof WebhookVerificationError) return c.json({ error: e.message }, 400);
      throw e;
    }
    if (seen.has(headers["svix-id"])) return c.json({ ok: true, duplicate: true });
    seen.add(headers["svix-id"]);
    onEvent(evt, headers["svix-id"]);
    return c.json({ ok: true });
  });
  return app;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { Webhook } from "svix";
import { makeApp, type Event } from "../src/app.ts";

// Svix secrets are base64 with a whsec_ prefix.
const SECRET = "whsec_" + Buffer.from("provenpin-test-secret-32-bytes!!").toString("base64");
const signer = new Webhook(SECRET);

function signed(body: string, id: string, ts = new Date()) {
  return {
    method: "POST",
    body,
    headers: {
      "content-type": "application/json",
      "svix-id": id,
      "svix-timestamp": String(Math.floor(ts.getTime() / 1000)),
      "svix-signature": signer.sign(id, ts, body),
    },
  };
}

test("valid signature is accepted and parsed", async () => {
  const got: [Event, string][] = [];
  const app = makeApp(SECRET, (e, id) => got.push([e, id]));
  const body = JSON.stringify({ type: "user.created", data: { id: "u_1" } });
  const res = await app.request("/webhooks", signed(body, "msg_1"));
  assert.equal(res.status, 200);
  assert.deepEqual(got, [[{ type: "user.created", data: { id: "u_1" } }, "msg_1"]]);
});

test("tampered body is rejected", async () => {
  const app = makeApp(SECRET, () => assert.fail("should not run"));
  const req = signed(JSON.stringify({ type: "a", data: {} }), "msg_2");
