import asyncio
import email.utils
from dataclasses import dataclass
from datetime import datetime, timezone

import httpx
from tenacity import AsyncRetrying, retry_if_exception, stop_after_attempt, wait_exponential

_backoff = wait_exponential(multiplier=0.5, max=8)


@dataclass(frozen=True)
class Repo:
    id: int
    full_name: str
    stargazers_count: int


def _retry_after(response: httpx.Response) -> float | None:
    value = response.headers.get("Retry-After")
    if value is None:
        return None
    if value.isdigit():
        return float(value)
    # Retry-After may also be an HTTP date
    try:
        when = email.utils.parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return None
    return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())


def _wait(retry_state) -> float:
    exc = retry_state.outcome.exception()
    if isinstance(exc, httpx.HTTPStatusError):
        delay = _retry_after(exc.response)
        if delay is not None:
            return delay
    return _backoff(retry_state)


def _should_retry(exc: BaseException) -> bool:
    if isinstance(exc, httpx.TransportError):
        return True
    if isinstance(exc, httpx.HTTPStatusError):
        code = exc.response.status_code
        return code == 429 or code >= 500
    return False


class ApiClient:
    def __init__(self, base_url: str = "https://api.example.com", attempts: int = 3, sleep=asyncio.sleep):
        self.http = httpx.AsyncClient(base_url=base_url, timeout=10)
        self.attempts = attempts
        self.sleep = sleep

    async def _get(self, path: str) -> httpx.Response:
        # A fresh AsyncRetrying per call: retry state lives on the instance,
        # so sharing one across concurrent calls would mix up their attempts.
        retrying = AsyncRetrying(
            stop=stop_after_attempt(self.attempts),
            wait=_wait,
            retry=retry_if_exception(_should_retry),
            sleep=self.sleep,
            reraise=True,  # raise the original error, not tenacity.RetryError
        )
        async for attempt in retrying:
            with attempt:
                r = await self.http.get(path)
                # must raise inside the block, or a 5xx is returned as a success and never retried
                r.raise_for_status()
        return r

    async def get_repo(self, owner: str, name: str) -> Repo:
        r = await self._get(f"/repos/{owner}/{name}")
        d = r.json()
        # pick known fields explicitly so extra API keys are ignored
        return Repo(id=d["id"], full_name=d["full_name"], stargazers_count=d["stargazers_count"])

    async def aclose(self):
        await self.http.aclose()

from tenacity import (
    Retrying,
    retry,
    retry_if_exception_type,
    stop_after_attempt,
    wait_exponential,
    wait_none,
)


class TransientError(Exception):
    pass


class FatalError(Exception):
    pass


def build_retryer(max_attempts=3, *, no_wait=True, reraise=True):
    return Retrying(
        stop=stop_after_attempt(max_attempts),
        wait=wait_none() if no_wait else wait_exponential(multiplier=1, min=1, max=10),
        retry=retry_if_exception_type(TransientError),
        reraise=reraise,
    )


def run_with_retry(fn, *args, max_attempts=3, no_wait=True, **kwargs):
    return build_retryer(max_attempts, no_wait=no_wait)(fn, *args, **kwargs)


@retry(
    stop=stop_after_attempt(3),
    wait=wait_none(),
    retry=retry_if_exception_type(TransientError),
    reraise=True,
)
def reload_config(loader, *args, **kwargs):
    return loader(*args, **kwargs)

import pytest
from tenacity import (
    RetryError,
    Retrying,
    retry_if_exception_type,
    stop_after_attempt,
    wait_exponential,
)

from retrier import (
    FatalError,
    TransientError,
    build_retryer,
    reload_config,
    run_with_retry,
)


def test_retries_transient_then_succeeds():
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise TransientError("warming up")
        return "ready"

    assert run_with_retry(flaky) == "ready"
    assert len(calls) == 3


def test_exhaustion_reraises_original_and_stops():
    calls = []

    def always_down():
        calls.append(1)
        raise TransientError("down")

    with pytest.raises(TransientError):
        run_with_retry(always_down, max_attempts=2)
    assert len(calls) == 2


def test_non_retryable_error_is_not_retried():
    calls = []

    def bad_request():
        calls.append(1)
        raise FatalError("400")

    with pytest.raises(FatalError):
        run_with_retry(bad_request)
    assert len(calls) == 1


def test_without_reraise_raises_retryerror():
    retryer = build_retryer(max_attempts=2, reraise=False)

    def always_down():
