import tomlkit
from tomlkit import TOMLDocument


def load(text: str) -> TOMLDocument:
    return tomlkit.parse(text)


def dump(doc: TOMLDocument) -> str:
    return tomlkit.dumps(doc)


def bump_version(doc: TOMLDocument, version: str) -> None:
    doc["project"]["version"] = version


def add_dependency(doc: TOMLDocument, dep: str) -> None:
    doc["project"]["dependencies"].append(dep)


def update_section(doc: TOMLDocument, name: str, values: dict) -> None:
    section = doc.setdefault(name, tomlkit.table())
    for key, value in values.items():
        section[key] = value


def add_note(doc: TOMLDocument, text: str) -> None:
    doc.add(tomlkit.comment(text))
    doc.add(tomlkit.nl())

from toolz import compose, curry, pipe
from cytoolz import curry as ccurry
from cytoolz.curried import map as cmap, filter as cfilter, reduce as creduce


@ccurry
def scale(factor, value):
    return factor * value


@ccurry
def bump(value, by):
    return value + by


def add_one(value):
    return value + 1


def running_total(values):
    # cmap is lazy, creduce consumes it left to right
    return creduce(bump, cmap(scale(2), values), 0)


def evens_plus_one(values):
    # returns a lazy cytoolz iterator, nothing runs until consumed
    return cmap(add_one, cfilter(lambda x: x % 2 == 0, values))

