import validator from "validator";

// validator is CommonJS: use the default export, named ESM imports fail at runtime.
const {
  escape,
  isEmail,
  isStrongPassword,
  isURL,
  isUUID,
  normalizeEmail,
  trim,
} = validator;

export type RawInput = {
  email?: unknown;
  website?: unknown;
  userId?: unknown;
  password?: unknown;
  note?: unknown;
};

export type CleanInput = {
  email: string;
  emailValid: boolean;
  website: string;
  websiteValid: boolean;
  userId: string;
  userIdValid: boolean;
  passwordScore: number;
  passwordStrong: boolean;
  note: string;
};

function str(value: unknown): string {
  return typeof value === "string" ? value : "";
}

export function scorePassword(password: string): number {
  return isStrongPassword(password, { returnScore: true }) as unknown as number;
}

export function cleanInput(input: RawInput): CleanInput {
  const email = trim(str(input.email));
  const website = trim(str(input.website));
  const userId = trim(str(input.userId)).toLowerCase();
  const password = str(input.password);
  const note = escape(trim(str(input.note)));

  return {
    email: normalizeEmail(email) || email,
    emailValid: isEmail(email),
    website,
    websiteValid: isURL(website, {
      require_protocol: true,
      protocols: ["http", "https"],
    }),
    userId,
    userIdValid: isUUID(userId, "4"),
    passwordScore: scorePassword(password),
    passwordStrong: isStrongPassword(password),
    note,
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { cleanInput, scorePassword } from "../src/sanitize.ts";

test("validates and normalizes an email", () => {
  const result = cleanInput({ email: "  Alice@Example.COM  " });
  assert.equal(result.emailValid, true);
  assert.equal(result.email, "alice@example.com");
});

test("flags malformed emails", () => {
  const result = cleanInput({ email: "not-an-email" });
  assert.equal(result.emailValid, false);
});

test("validates URLs with protocol options", () => {
  assert.equal(cleanInput({ website: "https://example.com" }).websiteValid, true);
  assert.equal(cleanInput({ website: "ftp://example.com" }).websiteValid, false);
});

test("validates UUID v4 values", () => {
  assert.equal(
    cleanInput({ userId: "F47AC10B-58CC-4372-A567-0E02B2C3D479" }).userIdValid,
    true,
  );
  assert.equal(cleanInput({ userId: "nope" }).userIdValid, false);
});

test("scores strong passwords higher than weak ones", () => {
  const weak = scorePassword("password");
  const strong = scorePassword("Str0ng!Passw0rd");
  assert.equal(cleanInput({ password: "password" }).passwordStrong, false);
  assert.equal(cleanInput({ password: "Str0ng!Passw0rd" }).passwordStrong, true);
  assert.ok(strong > weak);
});

test("escapes and trims notes with sanitizers", () => {
  const result = cleanInput({ note: "  <b>hi & bye  " });
  assert.equal(result.note, "&lt;b&gt;hi &amp; bye");
});

{
  "name": "valtio-proxy-state",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "valtio": "2.3.2"
  },
  "devDependencies": {
    "@types/node": "26.6.5",
    "tsx": "4.23.15"
  }
}

import { proxy, snapshot, subscribe } from "valtio/vanilla";

export type Todo = { id: number; text: string; done: boolean };
export type Store = { todos: Todo[]; nextId: number };

export function createStore(): Store {
  return proxy({ todos: [] as Todo[], nextId: 1 });
}

export function addTodo(store: Store, text: string) {
  store.todos.push({ id: store.nextId++, text, done: false });
}

export function toggle(store: Store, id: number) {
  const t = store.todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
}

export function openCount(store: Store) {
  return snapshot(store).todos.filter((t) => !t.done).length;
}

export function watch(store: Store, fn: () => void) {
  return subscribe(store, fn);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { snapshot } from "valtio/vanilla";
import { addTodo, createStore, openCount, toggle, watch } from "../src/store.ts";

test("proxy mutations notify subscribers and snapshot is immutable", async () => {
  const store = createStore();
  let ticks = 0;
  const unsub = watch(store, () => { ticks++; });
  addTodo(store, "ship");
  addTodo(store, "docs");
  toggle(store, 1);
  await Promise.resolve();
  assert.ok(ticks >= 1);
  assert.equal(openCount(store), 1);
  const snap = snapshot(store);
  assert.equal(snap.todos[0].done, true);
  assert.throws(() => { (snap.todos[0] as { done: boolean }).done = false; });
  unsub();
});

