}

import { generateText, streamText, tool, stepCountIs, Output, type LanguageModel } from "ai";
import { z } from "zod";

/** Fake inventory the tool reads from; real code would hit a database or API. */
const STOCK: Record<string, { name: string; qty: number; priceCents: number }> = {
  "SKU-1": { name: "Hard hat", qty: 12, priceCents: 2499 },
  "SKU-2": { name: "Safety glasses", qty: 0, priceCents: 899 },
};

export const tools = {
  checkStock: tool({
    description: "Look up stock and price for a SKU",
    inputSchema: z.object({ sku: z.string().regex(/^SKU-\d+$/) }),
    execute: async ({ sku }) => STOCK[sku] ?? { error: "unknown sku" },
  }),
};

/** Multi-step tool loop: the model may call checkStock, then answers in text. */
export function answerStockQuestion(model: LanguageModel, question: string) {
  return generateText({
    model,
    system: "You answer stock questions. Use the checkStock tool, never guess.",
    prompt: question,
    tools,
    stopWhen: stepCountIs(3),
  });
}

export const Ticket = z.object({
  category: z.enum(["billing", "bug", "feature"]),
  priority: z.enum(["low", "medium", "high"]),
  summary: z.string().max(80),
});

/** Structured output validated against a Zod schema. */
export async function triage(model: LanguageModel, email: string) {
  const r = await generateText({ model, prompt: `Triage this support email:\n${email}`, output: Output.object({ schema: Ticket }) });
  return r.output;
}

/** Streams text deltas and returns them joined, plus the final usage. */
export async function streamSummary(model: LanguageModel, text: string, onDelta: (d: string) => void) {
  const r = streamText({ model, prompt: `Summarise: ${text}` });
  for await (const delta of r.textStream) onDelta(delta);
  return { text: await r.text, usage: await r.totalUsage };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { MockLanguageModelV4, simulateReadableStream } from "ai/test";
import { answerStockQuestion, triage, streamSummary } from "../src/agent.ts";

const usage = (input: number, output: number) => ({
  inputTokens: { total: input, noCache: input, cacheRead: undefined, cacheWrite: undefined },
  outputTokens: { total: output, text: output, reasoning: undefined },
});
const finish = (unified: "stop" | "tool-calls") => ({ unified, raw: unified });

test("tool loop: model calls checkStock, gets the result, then answers", async () => {
  const model = new MockLanguageModelV4({
    doGenerate: [
      { content: [{ type: "tool-call", toolCallId: "call-1", toolName: "checkStock", input: JSON.stringify({ sku: "SKU-1" }) }], finishReason: finish("tool-calls"), usage: usage(20, 5), warnings: [] },
      { content: [{ type: "text", text: "We have 12 hard hats at $24.99." }], finishReason: finish("stop"), usage: usage(40, 10), warnings: [] },
    ],
  });
  const r = await answerStockQuestion(model, "How many hard hats are in stock?");
  assert.equal(r.text, "We have 12 hard hats at $24.99.");
  assert.equal(r.steps.length, 2);
  assert.deepEqual(r.steps[0].toolResults.map((t) => t.output), [{ name: "Hard hat", qty: 12, priceCents: 2499 }]);
  assert.equal(r.totalUsage.inputTokens, 60);
  // The second model call must include the tool result in its prompt.
  const second = JSON.stringify(model.doGenerateCalls[1].prompt);
  assert.match(second, /"qty":12/);
  assert.equal(model.doGenerateCalls[0].tools?.[0].name, "checkStock");
});

test("stopWhen caps a model that keeps calling tools", async () => {
  const call = { content: [{ type: "tool-call" as const, toolCallId: "c", toolName: "checkStock", input: '{"sku":"SKU-2"}' }], finishReason: finish("tool-calls"), usage: usage(1, 1), warnings: [] };
  const model = new MockLanguageModelV4({ doGenerate: async () => call });
  const r = await answerStockQuestion(model, "loop forever");
  assert.equal(r.steps.length, 3);
  assert.equal(model.doGenerateCalls.length, 3);
});

test("structured output is parsed and validated with the zod schema", async () => {
  const good = new MockLanguageModelV4({ doGenerate: { content: [{ type: "text", text: JSON.stringify({ category: "billing", priority: "high", summary: "Charged twice" }) }], finishReason: finish("stop"), usage: usage(30, 12), warnings: [] } });
  assert.deepEqual(await triage(good, "I was charged twice!"), { category: "billing", priority: "high", summary: "Charged twice" });
  assert.equal(good.doGenerateCalls[0].responseFormat?.type, "json");

  const bad = new MockLanguageModelV4({ doGenerate: { content: [{ type: "text", text: JSON.stringify({ category: "spam", priority: "high", summary: "x" }) }], finishReason: finish("stop"), usage: usage(1, 1), warnings: [] } });
  await assert.rejects(triage(bad, "?"));
});

test("streamText delivers deltas in order", async () => {
  const model = new MockLanguageModelV4({
    doStream: async () => ({
      stream: simulateReadableStream({
        chunks: [
          { type: "stream-start", warnings: [] },
          { type: "text-start", id: "t1" },
          { type: "text-delta", id: "t1", delta: "Short " },
          { type: "text-delta", id: "t1", delta: "and " },
          { type: "text-delta", id: "t1", delta: "sweet." },
          { type: "text-end", id: "t1" },
          { type: "finish", finishReason: finish("stop"), usage: usage(8, 3) },
        ],
      }),
    }),
  });
  const deltas: string[] = [];
  const r = await streamSummary(model, "a long text", (d) => deltas.push(d));
  assert.deepEqual(deltas, ["Short ", "and ", "sweet."]);
  assert.equal(r.text, "Short and sweet.");
  assert.equal(r.usage.outputTokens, 3);
});

{
  "name": "viem-offline-sign-verify",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "viem": "2.57.7"
  },
  "devDependencies": {
    "@types/node": "26.6.5",
    "tsx": "4.23.15"
  }
}

import { privateKeyToAccount } from "viem/accounts";
import {
  decodeFunctionData,
  encodeFunctionData,
  erc20Abi,
  formatUnits,
  parseUnits,
  recoverTypedDataAddress,
  verifyMessage,
  type Address,
  type Hex,
} from "viem";

export const TEST_PRIVATE_KEY =
  "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80" as const;

export const account = privateKeyToAccount(TEST_PRIVATE_KEY);

export async function signAndVerifyMessage(
  message: string,
): Promise<{ signature: Hex; valid: boolean }> {
  const signature = await account.signMessage({ message });
  const valid = await verifyMessage({
    address: account.address,
    message,
    signature,
  });
  return { signature, valid };
}

export type TransferIntent = {
  token: Address;
  to: Address;
  value: bigint;
  nonce: bigint;
};

export async function signTypedDataAndRecover(
  intent: TransferIntent,
): Promise<{ signature: Hex; recovered: Address }> {
  const typedData = {
    domain: {
      name: "ProvenPinToken",
      version: "1",
      chainId: 1,
      verifyingContract: intent.token,
    },
    types: {
      Transfer: [
        { name: "to", type: "address" },
        { name: "value", type: "uint256" },
        { name: "nonce", type: "uint256" },
      ],
    },
    primaryType: "Transfer",
    message: {
      to: intent.to,
      value: intent.value,
      nonce: intent.nonce,
    },
  } as const;

  const signature = await account.signTypedData(typedData);
  const recovered = await recoverTypedDataAddress({ ...typedData, signature });
  return { signature, recovered };
}

export function encodeTransfer(to: Address, amount: bigint): Hex {
  return encodeFunctionData({
    abi: erc20Abi,
    functionName: "transfer",
    args: [to, amount],
  });
}

export function decodeTransfer(data: Hex): { to: Address; amount: bigint } {
  const decoded = decodeFunctionData({ abi: erc20Abi, data });
  if (decoded.functionName !== "transfer") {
    throw new Error(`unexpected function selector: ${decoded.functionName}`);
  }
  const [to, amount] = decoded.args as readonly [Address, bigint];
  return { to, amount };
}

export function toBaseUnits(amount: string, decimals = 18): bigint {
  return parseUnits(amount, decimals);
}

export function fromBaseUnits(amount: bigint, decimals = 18): string {
  return formatUnits(amount, decimals);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { verifyMessage } from "viem";
import {
  TEST_PRIVATE_KEY,
  account,
  decodeTransfer,
  encodeTransfer,
  fromBaseUnits,
  signAndVerifyMessage,
  signTypedDataAndRecover,
  toBaseUnits,
} from "../src/sign.ts";

const EXPECTED_ADDRESS = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266";

test("derives a deterministic account offline from the fixed key", () => {
  assert.equal(TEST_PRIVATE_KEY.length, 66);
  assert.equal(account.address.toLowerCase(), EXPECTED_ADDRESS.toLowerCase());
});

test("signs a message and verifies it offline", async () => {
  const { signature, valid } = await signAndVerifyMessage("hello provenpin");
  assert.match(signature, /^0x[0-9a-f]+$/);
  assert.equal(valid, true);
});

test("verifyMessage rejects a tampered message", async () => {
  const { signature } = await signAndVerifyMessage("hello provenpin");
  const valid = await verifyMessage({
    address: account.address,
    message: "hello tampered",
    signature,
  });
  assert.equal(valid, false);
});

test("signs EIP-712 typed data and recovers the signer", async () => {
  const { signature, recovered } = await signTypedDataAndRecover({
    token: "0x0000000000000000000000000000000000000001",
    to: "0x0000000000000000000000000000000000000002",
    value: 1_000_000n,
    nonce: 7n,
  });
  assert.match(signature, /^0x[0-9a-f]+$/);
  assert.equal(recovered.toLowerCase(), account.address.toLowerCase());
});

test("encodes and decodes an ERC-20 transfer call offline", () => {
  const amount = toBaseUnits("1.5", 18);
  assert.equal(amount, 1_500_000_000_000_000_000n);
  const data = encodeTransfer(EXPECTED_ADDRESS, amount);
  assert.equal(data.slice(0, 10), "0xa9059cbb");
  const decoded = decodeTransfer(data);
  assert.equal(decoded.to.toLowerCase(), EXPECTED_ADDRESS.toLowerCase());
  assert.equal(decoded.amount, amount);
  assert.equal(fromBaseUnits(amount, 18), "1.5");
});

test("parseUnits/formatUnits round-trip for 6 decimals", () => {
  const units = toBaseUnits("12.34", 6);
  assert.equal(units, 12_340_000n);
