    const auto = createAutosave(save, 500);
    auto.change("h");
    vi.advanceTimersByTime(200);
    auto.change("he");
    vi.advanceTimersByTime(200);
    auto.change("hey");
    expect(save).not.toHaveBeenCalled();
    vi.advanceTimersByTime(500);
    expect(save).toHaveBeenCalledTimes(1);
    expect(save).toHaveBeenCalledWith("hey");
